private static final Set<String> ALLOWED_EXT = Set.of("png", "jpg", "jpeg", "pdf");

private void validate(MultipartFile file) throws IOException {
    String ext = extractExt(file.getOriginalFilename()).toLowerCase();
    if (!ALLOWED_EXT.contains(ext)) {
        throw new InvalidFileException("허용하지 않는 형식입니다");
    }

    // 실제 내용 확인 - PNG 는 89 50 4E 47 로 시작한다
    byte[] head = new byte[4];
    try (InputStream in = file.getInputStream()) {
        if (in.read(head) < 4) {
            throw new InvalidFileException("파일이 손상되었습니다");
        }
    }
    if (ext.equals("png") && !isPng(head)) {
        throw new InvalidFileException("내용이 형식과 다릅니다");
    }
}
